package com.kongye.floatball;
import android.content.Context;
import android.graphics.*;
import android.media.MediaMetadataRetriever;
import java.io.*;
import java.util.function.*;
final class GifConversion {
    static File convert(Context c,File video,int shortSide,long startMs,long durationMs,BooleanSupplier cancelled,IntConsumer progress)throws Exception{MediaMetadataRetriever reader=new MediaMetadataRetriever();File file=RecordingFiles.create(c,"gif");boolean success=false;try{reader.setDataSource(video.getPath());long total=Long.parseLong(reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));startMs=Math.max(0,Math.min(total-1,startMs));durationMs=Math.min(30000,Math.min(durationMs,total-startMs));if(durationMs<100)throw new IOException("视频时间太短");int w=Integer.parseInt(reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),h=Integer.parseInt(reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));float scale=Math.min(1f,Math.min(shortSide/(float)Math.min(w,h),960f/Math.max(w,h)));w=Math.max(2,Math.round(w*scale));h=Math.max(2,Math.round(h*scale));try(GifWriter writer=new GifWriter(new BufferedOutputStream(new FileOutputStream(file)),w,h)){int frames=(int)Math.max(1,(durationMs+199)/200);for(int i=0;i<frames;i++){if(cancelled.getAsBoolean())throw new InterruptedIOException("已取消转换");Bitmap frame=android.os.Build.VERSION.SDK_INT>=27?reader.getScaledFrameAtTime((startMs+i*200)*1000,MediaMetadataRetriever.OPTION_CLOSEST,w,h):reader.getFrameAtTime((startMs+i*200)*1000,MediaMetadataRetriever.OPTION_CLOSEST);if(frame==null)throw new IOException("无法解码视频帧");Bitmap sized=frame.getWidth()==w&&frame.getHeight()==h?frame:Bitmap.createScaledBitmap(frame,w,h,true);writer.frame(sized,(int)Math.min(200,durationMs-i*200));if(sized!=frame)sized.recycle();frame.recycle();progress.accept((i+1)*100/frames);if(file.length()>100*1024*1024)throw new IOException("GIF 过大，请缩短时间或降低分辨率");}}success=true;return file;}finally{try{reader.release();}catch(IOException ignored){}if(!success)file.delete();}}
}
